L = 'LENTA/lenta.md'; s = open(L).read(); bad = []
for i, (a, b) in enumerate(E, 1):
    c = s.count(a)
    if c != 1: bad.append((i, c, a[:60])); continue
    s = s.replace(a, b)
open(L, 'w').write(s)
print("применено:", len(E) - len(bad), "из", len(E)); [print("  не применено", x) for x in bad]
